/**
 * Official Japanese local-government directory, source snapshot 2026-10-12.
 * Generated by exact prefecture/name join of J-LIS code-address and map-search
 * public tables. Rows contain factual code/name/link-host data only; no slogans.
 * 1,741 municipalities and 47 prefectures. Designated-city administrative wards
 * are not separate recipient authorities. Their parent city is the authority.
 * A website host is evidence of the published official link, not proof of email
 * ownership. Custom/non-government hostnames are retained for discovery but do
 * not become email verification domains without an explicitly published alias.
 * This snapshot has 1,673 identities with a supported exact-domain candidate;
 * 115 custom-host identities have no supported authentication domain. A domain
 * candidate does not guarantee that every department uses that email domain.
 * Restricted-domain classification references:
 * https://www.j-lis.go.jp/lgwan/lgjp/summary/cms_15365140.html
 * https://jprs.jp/doc/rule/prefecturejp-reserved.html
 * https://jprs.jp/glossary/index.php?ID=0082
 * Website links in the consumer are normalized HTTPS roots of these link hosts;
 * redirects, availability, departmental mailbox coverage were not exhaustively
 * tested. Follow source links when the normalized root is unavailable.
 *
 * Regeneration: refresh all listed official sources; join exact prefecture/name
 * with the six-digit code; reject duplicate/missing identities, conflicting host
 * assignments and administrative wards; retain source URLs and retrieval date.
 * Add email aliases only from a fresh official page publishing that mailbox.
 * Unknown applicant domains never become input to this source directory.
 */

export type MunicipalityDirectoryRow = readonly [
  code: string, name: string, prefecture: string, officialLinkHost: string,
  websiteSourceIndex: number, codeSourceIndex: number, officialDomainCandidate: boolean,
];

